/// <summary>
///
/// </summary>
public void initValue()
{
    super();
    this.IsActive         = NoYes::Yes;
    this.ValidFrom        = systemDateGet();
    this.ValidTo          = dateMax();
    this.LegalEntity      = curExt();
    this.MSFRate          = 1.10;        // Default 1.10% MSF
    this.GSTRate          = 18.0;        // Default 18% GST
    this.IsIntraState     = NoYes::Yes;  // Default intra-state
    this.StateCode        = 'RJ';        // Default Rajasthan
    this.SysCreatedBy        = curUserId();
    this.SysCreatedDateTime  = DateTimeUtil::utcNow();
}

/// <summary>
///
/// </summary>
public void update()
{
    this.UserModifiedBy       = curUserId();
    this.UserModifiedDateTime = DateTimeUtil::utcNow();
    super();
}

/// <summary>
///
/// </summary>
/// <returns></returns>
public boolean validateWrite()
{
    boolean ret = super();

    if (!this.TerminalId)
        ret = checkFailed("Terminal ID is mandatory.");

    if (!this.BranchCode)
        ret = checkFailed("Branch Code is mandatory.");

    if (!this.POSReceivableAccount)
        ret = checkFailed("POS Receivable Account is mandatory.");

    if (this.MSFRate < 0 || this.MSFRate > 5)
        ret = checkFailed("MSF Rate must be between 0% and 5%.");

    // The clearing bank is where the collection already sits (PhonePe, MobiKwik,
    // PayZapp); the settlement bank is where the acquirer pays it out. The same account
    // on both sides would post a debit and a credit to one bank and clear nothing.
    if (this.ClearingBankAccount && this.ClearingBankAccount == this.SettlementBankAccount)
        ret = checkFailed("Clearing bank account must differ from the settlement bank account.");

    // A window that ends before it starts silently hides the row: findByTerminalId
    // filters on ValidFrom <= today <= ValidTo, so the terminal reads as unmapped and
    // its settlements land in the manual queue with no obvious cause. Terminal
    // 41959954 was saved as 26-08-2026 to 30-04-2026 and did exactly that.
    if (this.ValidFrom && this.ValidTo && this.ValidTo < this.ValidFrom)
    {
        ret = checkFailed(strFmt(
            "Valid to (%1) is earlier than Valid from (%2). The terminal would never be found.",
            this.ValidTo, this.ValidFrom));
    }

    return ret;
}

/// <summary>
///
/// </summary>
public static boolean isIntraState(PremTerminalId _terminalId)
{
    PremPOSTerminalMap map = PremPOSTerminalMap::findByTerminalId(_terminalId);
    return map.IsIntraState == NoYes::Yes;
}

/// <summary>
///
/// </summary>

public static PremPOSTerminalMap findByTerminalId(PremTerminalId _terminalId)
{
    PremPOSTerminalMap map;

    select firstonly map
    where map.TerminalId == _terminalId
       && map.IsActive   == NoYes::Yes
       && map.ValidFrom  <= systemDateGet()
       && map.ValidTo    >= systemDateGet();

    return map;
}

/// <summary>
/// Bank account the acquirer credits this terminal's settlements into.
/// </summary>
public static BankAccountID getSettlementBankAccount(PremTerminalId _terminalId)
{
    PremPOSTerminalMap map = PremPOSTerminalMap::findByTerminalId(_terminalId);
    return map.SettlementBankAccount;
}

/// <summary>
///
/// </summary>
public static LedgerDimensionAccount getReceivableAccount(PremTerminalId _terminalId)
{
    PremPOSTerminalMap map = PremPOSTerminalMap::findByTerminalId(_terminalId);
    return map.POSReceivableAccount;
}

/// <summary>
/// Active terminal for a merchant code, such as the MID the bank prints in the narration
/// "UPI SETTLEMENT -CZL057- 07/10/26".
/// </summary>
public static PremPOSTerminalMap findByMerchantId(PremMerchantId _merchantId)
{
    PremPOSTerminalMap map;

    if (_merchantId)
    {
        select firstonly map
        where map.MerchantId == _merchantId
           && map.IsActive   == NoYes::Yes
           && map.ValidFrom  <= systemDateGet()
           && map.ValidTo    >= systemDateGet();
    }

    return map;
}

/// <summary>
/// Account type of the POS credit in the settlement entry (bank Dr + MSF Dr = POS Cr).
/// </summary>
/// <remarks>
/// PhonePe, MobiKwik and PayZapp collections sit in their own bank accounts in Cash and
/// bank management, so their POS credit posts as a bank line and the bank register stays
/// in step with the ledger. Terminals without a clearing bank (PineLabs) keep the POS
/// receivable ledger account.
/// </remarks>
public LedgerJournalACType posCreditAccountType()
{
    return this.ClearingBankAccount ? LedgerJournalACType::Bank : LedgerJournalACType::Ledger;
}

/// <summary>
/// Ledger dimension of the POS credit: the clearing bank account when one is set,
/// otherwise the POS receivable account.
/// </summary>
public DimensionDynamicAccount posCreditLedgerDimension()
{
    if (this.ClearingBankAccount)
    {
        return LedgerDynamicAccountHelper::getDynamicAccountFromAccountNumber(
            this.ClearingBankAccount, LedgerJournalACType::Bank);
    }

    return this.POSReceivableAccount;
}

/// <summary>
/// Sets the account of the POS credit line of a settlement journal for this terminal.
/// The caller still sets amount, date, voucher and text.
/// </summary>
public void initPOSCreditLine(LedgerJournalTrans _journalTrans)
{
    _journalTrans.AccountType     = this.posCreditAccountType();
    _journalTrans.LedgerDimension = this.posCreditLedgerDimension();

    if (this.ClearingBankAccount)
    {
        // Bank main accounts need the bank's own dimensions (BRANCH) to validate.
        _journalTrans.DefaultDimension = PremBankRecHelper::bankDefaultDimension(this.ClearingBankAccount);
    }
}
